"""Salesforce Fundamentals (part): object, record and field access and
choosing a sharing solution."""
from helpers import single, multi, assign

ITEMS = assign([
    # ---------------- Test 1 ----------------
    single("Org-wide defaults", 1,
           "Every user must see all accounts but edit only the accounts they own. Which org-wide default fits Account?",
           ["Public Read Only", "Private", "Public Read/Write", "Controlled by Parent"],
           "Public Read Only lets everyone view every record while only the owner, and users above in the role hierarchy, can edit. Public Read/Write would let everyone edit."),
    single("Field-level security", 1,
           "Where in Setup can an app builder see and change one field's access for every profile on a single screen?",
           ["Field Accessibility", "Setup Audit Trail", "Sharing Settings", "Login Access Policies"],
           "Field Accessibility shows a field's visibility and read-only state by profile or by record type in one grid. Sharing Settings controls record access, not field access."),
    multi("Sharing rules", 2,
          "Which two can a sharing rule share records with? (Choose two.)",
          ["Public groups", "Roles and subordinates", "Profiles", "Permission sets"],
          "Sharing rules grant access to public groups, roles, roles and subordinates, and territories where they are enabled. They cannot target a profile or a permission set."),
    single("Queues", 2,
           "A support queue should include everyone in the Support role automatically. What should be added as a member?",
           ["The Support role", "The Support profile", "A permission set group", "A sharing rule"],
           "Queue members can be users, public groups, roles, and roles and subordinates, so adding the role keeps membership current. Profiles cannot be queue members."),
    single("Permission sets", 2,
           "Permission sets should be assigned automatically whenever a user's Department is Finance. What fits?",
           ["User access policy", "Permission set group", "Profile default setting", "Criteria-based sharing rule"],
           "A user access policy assigns or removes permission sets, permission set groups, licenses, groups and queues when users match its criteria. A permission set group only bundles permission sets for manual assignment."),
    single("Object permissions", 2,
           "A user must edit, delete and transfer every Project__c record but needs no other org-wide power. Which permission fits?",
           ["Modify All on Project__c", "Modify All Data", "View All on Project__c", "Public Read/Write default"],
           "Modify All on one object grants read, edit, delete, transfer and approve on all its records, ignoring sharing. Modify All Data does that for every object, which is far more than needed."),

    # ---------------- Test 2 ----------------
    single("Org-wide defaults", 2,
           "On a custom object, managers must not automatically see the records their reports own. What should be cleared?",
           ["Grant Access Using Hierarchies", "View All on the custom object", "The object's sharing rules", "Manual sharing on records"],
           "Clearing Grant Access Using Hierarchies on a custom object means only the owner and users given access through sharing see its private records. This option can be turned off for custom objects only."),
    single("Field-level security", 2,
           "A field is editable on the page layout but read-only in the user's field permissions. What can the user do?",
           ["View it but not edit it", "Edit it on the record page", "Edit it only in list views", "Not see it at all"],
           "When the page layout and field permissions disagree, the more restrictive setting wins. Read-only field access means the user sees the value and cannot change it."),
    single("Restriction rules", 3,
           "Contractors need to see only the Project__c records in their region, while employees keep their wider access. Which feature narrows what the contractors see?",
           ["Restriction rule", "Sharing rule", "Permission set group", "Role hierarchy"],
           "A restriction rule limits which records a set of users can see, even when org-wide defaults or sharing would show more. Sharing rules and the role hierarchy can only add access."),
    single("Teams", 1,
           "Several reps must share access to one large opportunity, each with a role such as Sales Engineer. What fits?",
           ["Opportunity team", "Opportunity sharing rule", "Public group", "Permission set group"],
           "An opportunity team gives named users access to one opportunity with a team role and an access level. A queue or public group is not tied to a single record."),
    single("Profiles", 2,
           "Which setting is assigned through a profile rather than a permission set?",
           ["Page layout assignment", "Object create permission", "Field edit access", "Apex class access"],
           "Page layouts are assigned by profile and record type. Object, field and Apex class access can all be granted through permission sets, which Salesforce recommends."),
    single("Manual sharing", 2,
           "The Sharing button is missing on records of a custom Project__c object. Which org-wide default is the likely cause?",
           ["Public Read/Write", "Private", "Public Read Only", "Private without hierarchy access"],
           "Manual sharing opens access beyond the default, so the Sharing button appears only when the default is less than Public Read/Write. With Public Read/Write everyone can already edit."),

    # ---------------- Drill only ----------------
    single("Profiles", 1,
           "Call center users must be blocked from logging in at night. Where should this be set?",
           ["Login hours on their profile", "Session timeout setting", "Permission set expiration date", "Password policies"],
           "Login hours are set on the profile, and users on that profile cannot log in outside them. Session timeout only ends idle sessions."),
    single("Permission sets", 2,
           "A contractor needs extra access for 30 days only. What is the simplest way to grant it?",
           ["Assignment with an expiration date", "Temporary custom profile", "Manual shares on each record", "Freezing the user once 30 days pass"],
           "Permission set and permission set group assignments can carry an expiration date, after which Salesforce removes them. A temporary profile would have to be swapped back by hand."),
    single("Session-based access", 3,
           "Extra access must be active only after the user signs in with multi-factor verification, not on every login. What fits?",
           ["Session-based permission set", "Permission set with an expiration date", "Permission set group with muting", "Login IP ranges on the profile"],
           "A session-based permission set is active only while its session activation condition is met, such as a high assurance session after multi-factor verification. An expiration date or muting does not depend on how the user signed in."),
    single("Custom permissions", 2,
           "Which feature lets a flow check whether the running user has been granted a named capability?",
           ["Custom permission", "Permission set group", "Field-level security", "Profile name check"],
           "A custom permission is a named switch granted through permission sets or profiles, and flows and formulas read it through \\$Permission. Checking a profile name breaks as soon as access is granted another way."),
    multi("Record ownership", 2,
          "Which two can own a lead or case record? (Choose two.)",
          ["A user", "A queue", "A role", "A public group"],
           "Records are owned by a user or, for objects that support it, a queue. Roles and public groups can receive shared access but cannot own records."),
    single("Teams", 2,
           "An account owner wants to give named colleagues, each with a role, access to one account and its opportunities. What fits?",
           ["Account team", "Opportunity team on each deal", "Public group sharing rule", "Queue for the account"],
           "An account team lists users with a team role and their access to the account and its related opportunities and cases. A sharing rule covers groups of records, not one account."),
    single("Object permissions", 2,
           "Turning on Delete for an object in a permission set also turns on which permissions?",
           ["Read and Edit", "Create and Read", "View All", "Modify All"],
           "Delete depends on Edit, and Edit depends on Read, so enabling Delete selects both. View All and Modify All are separate, broader permissions."),
    single("Permission set groups", 1,
           "Every new recruiter needs the same five permission sets, assigned in one step. What fits?",
           ["Permission set group", "Permission set license", "Muting permission set", "Cloned standard profile"],
           "A permission set group bundles permission sets so one assignment gives all of them. A muting permission set only removes permissions inside a group, and a permission set license grants the right to use certain features."),
    single("Org-wide defaults", 2,
           "When planning record access, how should org-wide defaults be set?",
           ["Most restrictive level, then open up", "Least restrictive, then lock down later", "Public Read Only for every object", "Same level as each profile"],
           "Salesforce advises setting defaults to the most restrictive level and then using the role hierarchy, sharing rules and manual sharing to grant more. Sharing tools cannot take access away."),
    single("Role hierarchy", 1,
           "What does the role hierarchy mainly control?",
           ["Record visibility up the chain", "Object permissions for each job", "Page layouts by job", "Login hours by team"],
           "Roles open access to records owned by users below in the hierarchy when defaults are less than Public Read/Write. Object permissions come from profiles and permission sets."),
], 6)
